//! 🧰️ Real paged collection construction matches independent wire decoding and conserves every physical owner.
use super::*;
use semio_framework_value::{DslValue,native_decoding::{NativeDecodeConstructionRecipient,NativeDecodeWorkRecipient,NativeReceiver},retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
struct Construction(RetainedCloneGrant,RetainedCloneProgress);
impl NativeDecodeConstructionRecipient for Construction{fn submitted(&self)->RetainedCloneProgress{self.1}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(self.0,d));Ok(self.0)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.1=self.1.checked_add(p)?;assert!(p.fits(g)&&p.fits(self.0));Ok(())}}
struct Work<'a>(&'a u64);
impl NativeDecodeWorkRecipient for Work<'_>{fn admits(&mut self,seen:u64,next:u64)->Result<bool,ValueError>{Ok(seen.checked_add(next).is_some_and(|n|n<=(*self.0).min(1)))}}
pub(crate) fn run<T:NativeReceive<DslValue>+Serialize>(row:&serde_json::Value,cut:Option<usize>,profile:&serde_json::Value){
 let s=&profile["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();
 let input=if row["entries"].is_array(){DslValue::Object(row["entries"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),DslValue::from(pair[1].clone()))).collect())}else{DslValue::from(serde_json::from_str::<serde_json::Value>(row["wire"].as_str().unwrap()).unwrap())};let(mut source,_,_)=semio_framework_value::testing::admit_owned_source(input,());let identity=std::ptr::from_ref(source.borrow().get());let mut receiver=T::receiver();let mut allow=|_|true;let mut control=NativeDecodeControl::new_retained(&mut allow);let mut output=None;let mut refused=false;
 let post=|p:RetainedCloneProgress,work:u64,heap:(usize,usize),bank:&mut RetainedCloneGrant,fuel:&mut u64|{assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).expect("native collection exhausted explicit CPU stock");};
 for at in 0..100000{if cut==Some(at){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let denied=RetainedCloneGrant{maximum_items:0,..g};let(turn,heap)=observe(||receiver.advance(source.borrow(),&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));
  let mut construction=Construction(g,Default::default());let mut work=Work(&fuel);let mut actual_work=0;let(result,heap)=observe(||control.with_work_recipient(&mut work,|control|control.with_construction_recipient(&mut construction,|control|{let turn=receiver.advance(source.borrow(),control,4096,g);actual_work=turn.work;turn.result})));let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());post(p,actual_work,heap,&mut bank,&mut fuel);if result.is_err(){assert_eq!(row["accepted"],false);refused=true;break}assert_eq!(std::ptr::from_ref(source.borrow().get()),identity);if receiver.output_ready(){let(turn,heap)=observe(||receiver.take(g));let(value,p)=turn.result.unwrap().expect("funded collection handoff");post(p,turn.work,heap,&mut bank,&mut fuel);assert_eq!(serde_json::to_value(&value).unwrap(),row["expected"]);output=Some(value);break}}
 if cut.is_none(){assert_eq!(refused,!row["accepted"].as_bool().unwrap());assert_eq!(output.is_some(),row["accepted"].as_bool().unwrap());}receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(turn,heap)=observe(||receiver.close_step(g));post(turn.result.unwrap().progress(),turn.work,heap,&mut bank,&mut fuel);}assert!(receiver.terminal_is_empty());
 if let Some(value)=output{let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native collection owns controlled retirement"));for _ in 0..100000{if close.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(result,heap)=observe(||close.step(g));let work=close.last_turn_work();post(result.unwrap().progress(),work,heap,&mut bank,&mut fuel);}assert!(close.terminal_is_empty());}
 for _ in 0..100000{if source.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:1,..bank};let(turn,heap)=observe(||source.close_step(g));post(turn.result.unwrap().progress(),turn.work,heap,&mut bank,&mut fuel);}assert!(source.terminal_is_empty());assert!(fuel>0);
}
#[test]
fn native_bounded_ui_collections_preserve_original_owners_on_refusal_and_cancellation(){let c:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for row in c["cases"].as_array().unwrap(){let wire=row["wire"].as_str().unwrap();let accepted=row["accepted"].as_bool().unwrap();let oracle=match row["kind"].as_str().unwrap(){"map"=>serde_json::from_str::<UiFixedMap<u64>>(wire).map(|v|serde_json::to_value(v).unwrap()),"bytes"=>serde_json::from_str::<UiFixedBytes>(wire).map(|v|serde_json::to_value(v).unwrap()),_=>serde_json::from_str::<UiFixedList<u64>>(wire).map(|v|serde_json::to_value(v).unwrap())};assert_eq!(oracle.is_ok(),accepted);if let Ok(value)=oracle{assert_eq!(value,row["expected"])}for cut in std::iter::once(None).chain(c["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){match row["kind"].as_str().unwrap(){"map"=>run::<UiFixedMap<u64>>(row,cut,&c),"bytes"=>run::<UiFixedBytes>(row,cut,&c),_=>run::<UiFixedList<u64>>(row,cut,&c)}}}}
